CREATE TABLE parcel_jobs(id text PRIMARY KEY,buyer_id text NOT NULL REFERENCES users(id),driver_id text NOT NULL REFERENCES users(id),vehicle_type text NOT NULL REFERENCES vehicle_types(code),description text NOT NULL,status text NOT NULL DEFAULT 'REQUESTED' CHECK(status IN ('REQUESTED','ACCEPTED','PICKED_UP','DELIVERED','CANCELLED')),pickup_address text NOT NULL,pickup_latitude double precision NOT NULL CHECK(pickup_latitude BETWEEN -90 AND 90),pickup_longitude double precision NOT NULL CHECK(pickup_longitude BETWEEN -180 AND 180),dropoff_address text NOT NULL,dropoff_latitude double precision NOT NULL CHECK(dropoff_latitude BETWEEN -90 AND 90),dropoff_longitude double precision NOT NULL CHECK(dropoff_longitude BETWEEN -180 AND 180),fare_kobo integer NOT NULL CHECK(fare_kobo>0 AND fare_kobo<=100000000),commission_bps integer NOT NULL CHECK(commission_bps BETWEEN 0 AND 10000),distance_km double precision NOT NULL,pricing jsonb NOT NULL,pickup_pin text NOT NULL,delivery_pin text NOT NULL,pin_failures integer NOT NULL DEFAULT 0,pin_locked_until timestamptz,driver_latitude double precision,driver_longitude double precision,location_at timestamptz,review_open boolean NOT NULL DEFAULT false,review_note text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX parcel_jobs_driver_idx ON parcel_jobs(driver_id,status);
CREATE INDEX parcel_jobs_buyer_idx ON parcel_jobs(buyer_id,created_at);
